#include "frontend.hpp"
#include "file_io.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("Original data required");Resources r(argv[1]);auto root=fs::temp_directory_path()/"openfo054_full_savegame_test";fs::remove_all(root);
 Frontend f(r,root);need(f.create_profile("Аргон"),"create named player");auto first_id=f.profile_id;f.enter_career();size_t starter=0;while(starter<f.cars.size()&&(f.cars[starter].car_class!=1||f.cars[starter].stats.price>4000||f.cars[starter].stats.price<=0))++starter;need(starter<f.cars.size(),"affordable native starter available");f.select_car(starter);need(f.buy_career_car(),"buy starter");int starter_price=f.cars[starter].stats.price;
 f.ambient_occlusion=false;f.water_ssr=false;f.music_volume=25;f.effects_volume=70;f.screen_width=1600;f.screen_height=900;f.fullscreen=true;f.choice.automatic=false;f.controls.assign(ControlSettings::Gas,'Z');f.save_profile();f.save_controls();
 Frontend resumed(r,root);need(!resumed.ambient_occlusion&&!resumed.water_ssr,"per-profile AO and SSR survive restart");need(resumed.profile_name=="Аргон"&&resumed.music_volume==25&&resumed.effects_volume==70&&resumed.screen_width==1600&&resumed.fullscreen&&!resumed.choice.automatic&&resumed.controls.keys[0]=='Z',"profile settings, transmission and controls survive relaunch");
 resumed.enter_career();for(size_t i=0;i<resumed.track_slots.size();++i)if(resumed.track_slots[i].level==7)resumed.select_track(i);need(resumed.begin_career_race(),"durable attempt starts");auto backup=resumed.profile_path.parent_path()/"savegame.bak.json";fs::remove(backup);fs::create_directory(backup);int unpaid=resumed.money;Json result=Json::array({{{"car",0},{"rank",1},{"time",180.},{"finished",true}}});resumed.complete_career_race(result,5,7);need(!resumed.profile_save_ok&&resumed.money==unpaid&&resumed.career_progress.pending,"failed result write rolls back award and remains retryable");fs::remove(backup);resumed.complete_career_race(result,5,7);need(resumed.profile_save_ok&&!resumed.career_progress.pending&&resumed.money==unpaid+resumed.career_rules.event(7)->prizes[0]+7,"retry commits the result once after write access restored");need(resumed.last_career_result.value("prop_hits",0)==5&&resumed.last_career_result.value("prop_bonus",0)==7,"result shows actual smash payout");int paid=resumed.money;resumed.complete_career_race(result,5,7);need(resumed.money==paid,"retried result remains idempotent");
 int expected=resumed.money,completed=0;for(int c=1;c<=3;++c)for(int stage=1;stage<=3;++stage)for(const auto&e:f.career_rules.events)if(e.car_class==c&&e.stage==stage){Frontend game(r,root);game.enter_career();for(size_t i=0;i<game.track_slots.size();++i)if(game.track_slots[i].level==e.level)game.select_track(i);need(game.choice.ai_profile_class==c,"opponents follow career class even with original class C starter");need(game.begin_career_race(),"saved campaign can start next native event");auto before=game.money;game.complete_career_race(Json::array({{{"car",0},{"rank",1},{"time",180.},{"finished",true}}}));need(game.money>=before+e.prizes[0],"actual listed event prize paid");game.complete_career_race(Json::array({{{"car",0},{"rank",1},{"time",180.},{"finished",true}}}));expected+=e.prizes[0];++completed;}
 expected+=4000+8000+25000;Frontend complete(r,root);complete.enter_career();need(completed==36&&complete.career_progress.positions.size()==36&&complete.career_progress.classes_paid[2]&&complete.money==expected,"all 36 road stages and all class prizes survive repeated process reload");
 for(size_t i=0;i<complete.track_slots.size();++i)if(complete.track_slots[i].level==25)complete.select_track(i);need(complete.choice.event=="RACE"&&complete.choice.laps==5&&complete.choice.bots==7&&complete.choice.ai_profile_class==1,"bonus arena is native class1 circuit with seven opponents");
 need(complete.create_profile("Другий"),"second profile creation");complete.enter_career();need(complete.money==4000&&complete.career_progress.positions.empty()&&complete.controls.keys[0]=='W',"new player has independent fresh progress and controls");need(complete.activate_profile(first_id)&&complete.career_progress.classes_paid[2],"first completed campaign selectable again");need(fs::exists(complete.profile_path)&&fs::exists(complete.settings_path),"separate savegame and settings files exist");
 fs::remove_all(root);std::cout<<"Named player -> starter -> all36career events -> save/relaunch -> campaign completion -> isolated second profile passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
